Step:

```js
function computeStep(state, random = Math.random) {
  if (state.status !== 'running') return state;
  const direction = resolveDirection(state.direction, state.pendingDirection);
  const vec = DIR_VECTORS[direction];
  const head = state.snake[0];
  const nextHead = { x: head.x + vec.x, y: head.y + vec.y };

  if (!inBounds(nextHead)) {
    return { ...state, direction, pendingDirection: direction, status: 'over' };
  }

  const ate = state.food && cellsEqual(nextHead, state.food);
  const snake = ate ? [nextHead, ...state.snake] : [nextHead, ...state.snake.slice(0, -1)];
  const body = snake.slice(1);
  if (body.some(c => cellsEqual(c, nextHead))) {
    return { ...state, snake, direction, pendingDirection: direction, status:'over' };
  }

  if (!ate) {
    return { ...state, snake, direction, pendingDirection: direction };
  }
  const score = state.score + 1;
  const food = spawnFood(snake, random);
  return {
    snake, food, direction, pendingDirection: direction, score,
    // 棋盘填满：无空格可放置食物，按当前得分结束本局
    status: food === null ? 'over' : 'running',
  };
}
```

