      return {
        snake: snake,
        food: state.food,
        direction: direction,
        pendingDirection: direction,
        score: state.score,
        status: STATUS_OVER,
      };
    }

    if (!ate) {
      return {
        snake: snake,
        food: state.food,
        direction: direction,
        pendingDirection: direction,
        score: state.score,
        status: STATUS_RUNNING,
      };
    }

