  let timerId = null;          // 主循环定时器
  let lastTickAt = 0;          // 上次推进时间戳（页面隐藏恢复后只推进单步）
  let randomSource = Math.random;
  let dom = null;              // 缓存的 DOM 引用
  let ctx = null;              // Canvas 2D 上下文
