    if (!food) return;
    const centerX = food.x * CELL + CELL / 2;
    const centerY = food.y * CELL + CELL / 2;
    context.fillStyle = '#f97316';
    context.beginPath();
    context.arc(centerX, centerY, CELL * 0.32, 0, Math.PI * 2);
