      timerId = null;
    }
  }

  function startLoop() {
    stopLoop();
    lastTickAt = 0;
    timerId = setInterval(tick, TICK_MS);
  }

  function tick() {
    if (!state || state.status !== STATUS_RUNNING) {
      stopLoop();
      return;
    }
    // 页面隐藏时浏览器会节流定时器：恢复后只推进单步，不做多步追赶
